func stage(ctx context.Context, in <-chan Item) <-chan Item {
    out := make(chan Item)
    go func() {
        defer close(out)
        for it := range in {
            select {
            case out <- transform(it):
            case <-ctx.Done():
                return          // потребитель ушёл — выходим, а не висим
            }
        }
    }()
    return out
}
